const o = $('Price Order').first().json;
const orderRow = $('Create Order').first().json;
const order = Array.isArray(orderRow) ? orderRow[0] : orderRow;
const shipRow = $input.first().json;
const shipment = Array.isArray(shipRow) ? shipRow[0] : shipRow;

const SITE = 'https://brasacommerce-web.netlify.app';
const trackUrl = SITE + '/#track/' + order.order_number;

const money = (n) => '$' + Number(n).toFixed(2);
const firstName = o.customer.full_name.split(' ')[0];

const etaLabel = new Date(shipment.eta_date + 'T00:00:00Z').toLocaleDateString('en-US', {
  weekday: 'long', month: 'long', day: 'numeric', timeZone: 'UTC'
});

const rows = o.lines.map(l => `
  <tr>
    <td style="padding:12px 0;border-bottom:1px solid #EBE3D8;font-family:Arial,sans-serif;font-size:14px;color:#2C2C2C;">
      ${l.product_name}<br><span style="color:#8C7B70;font-size:12px;">${l.sku} · Qty ${l.qty}</span>
    </td>
    <td align="right" style="padding:12px 0;border-bottom:1px solid #EBE3D8;font-family:Arial,sans-serif;font-size:14px;color:#2C2C2C;white-space:nowrap;">
      ${money(l.line_total)}
    </td>
  </tr>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"></head>
<body style="margin:0;padding:0;background:#F5F0EA;">
<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:32px 16px;">
<table width="620" cellpadding="0" cellspacing="0" style="max-width:620px;">

  <tr><td style="padding:20px 32px;text-align:center;">
    <img src="https://mjfvjogsknnuizsoygpp.supabase.co/storage/v1/object/public/assets/brasa-logo.svg" alt="Brasa Commerce" style="height:56px;width:auto;display:block;margin:0 auto;border:0;">
  </td></tr>

  <tr><td style="background:#C2522A;padding:36px 32px;text-align:center;border-radius:12px 12px 0 0;">
    <div style="display:inline-block;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.35);border-radius:100px;padding:5px 18px;font-size:11px;font-weight:700;color:#fff;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;font-family:Arial,sans-serif;">Order Confirmed</div>
    <div style="font-family:Georgia,serif;font-size:30px;color:#fff;">${order.order_number}</div>
  </td></tr>

  <tr><td style="background:#fff;padding:32px;">
    <p style="font-family:Arial,sans-serif;font-size:15px;color:#2C2C2C;margin:0 0 18px;">Hi ${firstName}, thanks for your order. We're getting it ready now.</p>

    <table width="100%" cellpadding="0" cellspacing="0">${rows}
      <tr><td style="padding:12px 0;font-family:Arial,sans-serif;font-size:14px;color:#8C7B70;">Subtotal</td>
          <td align="right" style="padding:12px 0;font-family:Arial,sans-serif;font-size:14px;color:#2C2C2C;">${money(o.subtotal)}</td></tr>
      <tr><td style="padding:0 0 12px;font-family:Arial,sans-serif;font-size:14px;color:#8C7B70;">Shipping</td>
          <td align="right" style="padding:0 0 12px;font-family:Arial,sans-serif;font-size:14px;color:#2C2C2C;">${o.shipping_cost === 0 ? 'Free' : money(o.shipping_cost)}</td></tr>
      <tr><td style="padding:12px 0;border-top:2px solid #2C2C2C;font-family:Georgia,serif;font-size:18px;color:#2C2C2C;">Total</td>
          <td align="right" style="padding:12px 0;border-top:2px solid #2C2C2C;font-family:Georgia,serif;font-size:18px;color:#2C2C2C;">${money(o.total)}</td></tr>
    </table>

    <p style="font-family:Arial,sans-serif;font-size:14px;color:#8C7B70;margin:24px 0 4px;">Estimated delivery</p>
    <p style="font-family:Georgia,serif;font-size:20px;color:#2C2C2C;margin:0 0 24px;">${etaLabel}</p>

    <p style="font-family:Arial,sans-serif;font-size:14px;color:#8C7B70;margin:0 0 4px;">Shipping to</p>
    <p style="font-family:Arial,sans-serif;font-size:14px;color:#2C2C2C;margin:0 0 28px;line-height:1.5;">
      ${o.customer.full_name}<br>${o.ship_to.line1}${o.ship_to.line2 ? '<br>' + o.ship_to.line2 : ''}<br>${o.ship_to.city}, ${o.ship_to.state} ${o.ship_to.postal_code}
    </p>

    <table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr>
      <td style="background:#2C2C2C;border-radius:100px;">
        <a href="${trackUrl}" style="display:inline-block;padding:14px 34px;font-family:Arial,sans-serif;font-size:14px;font-weight:bold;color:#fff;text-decoration:none;">Track your order</a>
      </td>
    </tr></table>

    <p style="font-family:Arial,sans-serif;font-size:12px;color:#8C7B70;margin:20px 0 0;text-align:center;">
      Keep this number handy — <strong>${order.order_number}</strong> is how you look up your order.
    </p>
  </td></tr>

  <tr><td style="background:#F5F0EA;padding:22px 32px;text-align:center;border-radius:0 0 12px 12px;">
    <p style="font-family:Arial,sans-serif;font-size:12px;color:#8C7B70;margin:0;">Brasa Commerce LLC · Chicago, IL</p>
  </td></tr>

</table></td></tr></table></body></html>`;

return [{ json: {
  from: 'onboarding@resend.dev',
  to: o.customer.email,
  subject: 'Order confirmed · ' + order.order_number + ' — Brasa Commerce',
  html,
  order_number: order.order_number,
  total: o.total,
  eta_date: shipment.eta_date
} }];

